from pathlib import Path
import json,base64
p=Path(__file__).parent
D={k:'data:image/png;base64,'+base64.b64encode((p/(k+'-Anim-PARTIEL.png')).read_bytes()).decode() for k in ['Sleep','Idle','Walk']}
s='''<!doctype html><html lang="fr"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Planches Méga-Tsareena</title><style>body{margin:0;background:#14221c;color:#e9f0e6;font:16px system-ui}main{max-width:1050px;margin:auto;padding:24px}.note{border-left:4px solid #e9bd75;background:#473922;padding:14px;line-height:1.45}h1{font-size:27px}h2{font-size:17px;margin:0 0 8px}.grid{display:grid;grid-template-columns:repeat(2,1fr);gap:15px}.card{padding:16px;background:#263b2f;border-radius:10px}.stage{background:#cbdcc1;height:280px;display:grid;place-items:center}.stage canvas{width:100%;height:100%;image-rendering:pixelated}button{padding:10px;border:0;border-radius:6px;background:#daead4;font-weight:bold}p{line-height:1.5}a{color:#c9f1bc}@media(max-width:650px){.grid{grid-template-columns:1fr}}</style><main><h1>Méga-Tsareena · planches en cours</h1><p class="note">Planches pixelisées issues des poses disponibles. Elles sont <strong>provisoires et partielles</strong> : bras et mouvements à retravailler, directions absentes, offsets et ombres à créer. Ne pas importer comme pack complet.</p><button id="play">Pause</button><div class="grid"><div class="card"><h2>Repos · avant-droite</h2><div class="stage"><canvas id="idleR" width="400" height="280"></canvas></div><p>2 images · 30 / 30 ticks</p></div><div class="card"><h2>Repos · avant-gauche</h2><div class="stage"><canvas id="idleL" width="400" height="280"></canvas></div><p>2 images · 30 / 30 ticks</p></div><div class="card"><h2>Marche en lévitation · avant-droite</h2><div class="stage"><canvas id="walk" width="400" height="280"></canvas></div><p>4 images · 8 / 10 / 8 / 10 ticks</p></div><div class="card"><h2>Sommeil · direction unique</h2><div class="stage"><canvas id="sleep" width="400" height="280"></canvas></div><p>2 images · 30 / 35 ticks</p></div></div><p>Planches : <a download="Idle-Anim-PARTIEL.png" href="__IDLE__">Repos</a> · <a download="Walk-Anim-PARTIEL.png" href="__WALK__">Marche</a> · <a download="Sleep-Anim-PARTIEL.png" href="__SLEEP__">Sommeil</a></p><p>Durées et dimensions basées sur Tsareena de SpriteCollab (baronessfaron). La lévitation est simulée dans l’aperçu, pas intégrée aux offsets.</p></main><script>
const data=__JSON__, imgs={};Object.entries(data).forEach(([k,v])=>{imgs[k]=new Image;imgs[k].src=v});let paused=false,start=performance.now(),time=0;document.querySelector('#play').onclick=()=>{paused=!paused;document.querySelector('#play').textContent=paused?'Reprendre':'Pause';if(!paused)start=performance.now()-time};const tiles=[['idleR','Idle',1,32,56,[30,30]],['idleL','Idle',7,32,56,[30,30]],['walk','Walk',1,32,56,[8,10,8,10]],['sleep','Sleep',0,32,40,[30,35]]];function frame(ms,d){let t=ms*60/1000%d.reduce((a,b)=>a+b,0);for(let i=0;i<d.length;i++){if(t<d[i])return i;t-=d[i]}return 0}function run(t){if(!paused)time=t-start;for(const [id,key,row,w,h,d] of tiles){let f=frame(time,d),c=document.querySelector('#'+id).getContext('2d');c.clearRect(0,0,400,280);c.imageSmoothingEnabled=false;let s=Math.min(5,260/h),sw=w*s,sh=h*s,dy=id==='walk'?[1,4,1,4][f]:0;if(imgs[key].complete&&imgs[key].naturalWidth)c.drawImage(imgs[key],f*w,row*h,w,h,(400-sw)/2,10-dy,sw,sh)}requestAnimationFrame(run)}requestAnimationFrame(run)
</script></html>'''
for k,v in D.items():s=s.replace('__'+k.upper()+'__',v)
s=s.replace('__JSON__',json.dumps(D));(p/'index.html').write_text(s,encoding='utf8')
